//! Built-in, original, free Luminos skins and capes (generated by `tools/make_skins.py`; no Mojang art).
//! The first skin is the default every new offline account wears.

pub struct BuiltinSkin {
    pub id: &'static str,
    pub name: &'static str,
    pub blurb: &'static str,
    pub slim: bool,
    pub png: &'static [u8],
}

pub struct BuiltinCape {
    pub id: &'static str,
    pub name: &'static str,
    pub blurb: &'static str,
    pub png: &'static [u8],
}

pub const SKINS: &[BuiltinSkin] = &[
    BuiltinSkin {
        id: "luminos-pilot",
        name: "Luminos Pilot",
        blurb: "Navy hoodie, pixel crescent, blue-lit eyes.",
        slim: false,
        png: include_bytes!("../assets/skins/luminos-pilot.png"),
    },
    BuiltinSkin {
        id: "luminos-moonlit",
        name: "Moonlit",
        blurb: "Pale robe and silver hair. Slim arms.",
        slim: true,
        png: include_bytes!("../assets/skins/luminos-moonlit.png"),
    },
    BuiltinSkin {
        id: "luminos-ember",
        name: "Ember",
        blurb: "Charcoal jacket with amber trim.",
        slim: false,
        png: include_bytes!("../assets/skins/luminos-ember.png"),
    },
    BuiltinSkin {
        id: "luminos-knight",
        name: "Dither Knight",
        blurb: "Steel plate with a blue sash.",
        slim: false,
        png: include_bytes!("../assets/skins/luminos-knight.png"),
    },
];

pub const CAPES: &[BuiltinCape] = &[BuiltinCape {
    id: "luminos-moon-cape",
    name: "Moon Cape",
    blurb: "A dithered moon over deep blue.",
    png: include_bytes!("../assets/skins/luminos-moon-cape.png"),
}];

pub const DEFAULT_SKIN_ID: &str = "luminos-pilot";

pub fn skin(id: &str) -> Option<&'static BuiltinSkin> {
    SKINS.iter().find(|s| s.id == id)
}

pub fn cape(id: &str) -> Option<&'static BuiltinCape> {
    CAPES.iter().find(|c| c.id == id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_builtin_is_a_real_png_of_the_right_size() {
        for s in SKINS {
            assert_eq!(&s.png[1..4], b"PNG", "{}", s.id);
            assert_eq!(u32::from_be_bytes(s.png[16..20].try_into().unwrap()), 64);
            assert_eq!(u32::from_be_bytes(s.png[20..24].try_into().unwrap()), 64);
        }
        for c in CAPES {
            assert_eq!(u32::from_be_bytes(c.png[16..20].try_into().unwrap()), 64);
            assert_eq!(u32::from_be_bytes(c.png[20..24].try_into().unwrap()), 32);
        }
        assert!(skin(DEFAULT_SKIN_ID).is_some());
    }
}
